//! Parity with the upstream `py_sod_metrics` implementation on 8-bit samples.
//!
//! `support/upstream_reference.rs` is generated by `scripts/gen_upstream_reference.py`.

#[expect(clippy::unreadable_literal, reason = "generated reference data")]
mod support {
    pub mod upstream_reference;
}

use approx::assert_abs_diff_eq;
use birefnet_metric::{EvaluationConfig, MetricsAggregator, Sample, ThresholdCurve};
use support::upstream_reference as reference;

const DIMS: [usize; 2] = [reference::HEIGHT, reference::WIDTH];

struct Expected {
    mae: f64,
    mse: f64,
    sm: f64,
    wfm: f64,
    adp_fm: f64,
    adp_em: f64,
    fm_curve: [f64; 256],
    em_curve: [f64; 256],
    biou_curve: [f64; 256],
}

fn cases() -> [(Sample, Expected); 2] {
    use reference::*;
    [
        (
            Sample::from_u8(&PRED_0, &GT_0, DIMS).unwrap(),
            Expected {
                mae: MAE_0,
                mse: MSE_0,
                sm: SM_0,
                wfm: WFM_0,
                adp_fm: ADP_FM_0,
                adp_em: ADP_EM_0,
                fm_curve: FM_CURVE_0,
                em_curve: EM_CURVE_0,
                biou_curve: BIOU_CURVE_0,
            },
        ),
        (
            Sample::from_u8(&PRED_1, &GT_1, DIMS).unwrap(),
            Expected {
                mae: MAE_1,
                mse: MSE_1,
                sm: SM_1,
                wfm: WFM_1,
                adp_fm: ADP_FM_1,
                adp_em: ADP_EM_1,
                fm_curve: FM_CURVE_1,
                em_curve: EM_CURVE_1,
                biou_curve: BIOU_CURVE_1,
            },
        ),
    ]
}

fn assert_curve(name: &str, actual: &ThresholdCurve, expected: &[f64; 256]) {
    for (idx, (a, e)) in actual.values().iter().zip(expected).enumerate() {
        assert!(
            (a - e).abs() <= 1e-9,
            "{name}[{idx}] (threshold {}): got {a}, expected {e}",
            255 - idx
        );
    }
}

#[test]
fn every_measure_matches_the_reference_implementation() {
    for (idx, (sample, expected)) in cases().into_iter().enumerate() {
        let config = EvaluationConfig::new();
        let scores = sample.scores(&config);
        assert_abs_diff_eq!(scores.mae, expected.mae, epsilon = 1e-12);
        assert_abs_diff_eq!(scores.mse, expected.mse, epsilon = 1e-12);
        assert_abs_diff_eq!(scores.s_measure, expected.sm, epsilon = 1e-9);
        assert_abs_diff_eq!(scores.weighted_f_measure, expected.wfm, epsilon = 1e-9);
        assert_abs_diff_eq!(scores.f_measure.adaptive, expected.adp_fm, epsilon = 1e-12);
        assert_abs_diff_eq!(scores.e_measure.adaptive, expected.adp_em, epsilon = 1e-12);
        assert_curve(
            &format!("fm[{idx}]"),
            &scores.f_measure.curve,
            &expected.fm_curve,
        );
        assert_curve(
            &format!("em[{idx}]"),
            &scores.e_measure.curve,
            &expected.em_curve,
        );
        assert_curve(&format!("biou[{idx}]"), &scores.biou, &expected.biou_curve);
    }
}

#[test]
fn aggregated_curves_average_per_threshold_before_maxima() {
    let mut aggregator = MetricsAggregator::new(EvaluationConfig::new());
    let cases = cases();
    for (sample, _) in &cases {
        aggregator.push(&sample.scores(aggregator.config()));
    }
    let summary = aggregator.summary().unwrap();

    let mean_curve: Vec<f64> = (0..256)
        .map(|i| f64::midpoint(cases[0].1.fm_curve[i], cases[1].1.fm_curve[i]))
        .collect();
    let max_of_mean = mean_curve.iter().copied().fold(f64::NEG_INFINITY, f64::max);
    assert_abs_diff_eq!(summary.f_measure.curve.max(), max_of_mean, epsilon = 1e-9);
    assert_abs_diff_eq!(
        summary.mae,
        f64::midpoint(cases[0].1.mae, cases[1].1.mae),
        epsilon = 1e-12
    );
}
